-- ========================================================
-- BigDevOps 平台数据库初始化脚本
-- 字符集: utf8mb4 / 排序规则: utf8mb4_unicode_ci
-- 说明: 包含全量 49 张数据表 DDL 结构 + 纯净系统基础数据 (管理员账号、菜单树、API、系统角色、Casbin规则等)
-- ========================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for casbin_rule
-- ----------------------------
DROP TABLE IF EXISTS `casbin_rule`;
CREATE TABLE `casbin_rule` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ptype` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v0` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v3` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v4` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v5` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_casbin_rule` (`ptype`,`v0`,`v1`,`v2`,`v3`,`v4`,`v5`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for code_git_servers
-- ----------------------------
DROP TABLE IF EXISTS `code_git_servers`;
CREATE TABLE `code_git_servers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置名称,例如''内部GitLab''',
  `platform` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台类型: gitlab / gitea',
  `endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务API地址,例如 https://gitlab.company.com',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '创建人ID(关联User表)',
  `auth_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '认证方式: token / password',
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名(密码认证时使用)',
  `token` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问令牌(PAT),建议加密存储',
  `skip_verify` tinyint(1) DEFAULT NULL COMMENT '是否跳过SSL证书验证(针对自签证书)',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '连接状态: connected / disconnected',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_code_git_servers_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for jenkins_build_param
-- ----------------------------
DROP TABLE IF EXISTS `jenkins_build_param`;
CREATE TABLE `jenkins_build_param` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数名称',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'string' COMMENT '类型(string/boolean/choice/reactiveChoice)',
  `default_value` text COLLATE utf8mb4_unicode_ci COMMENT '默认值',
  `choices` longtext COLLATE utf8mb4_unicode_ci COMMENT '静态下拉选项',
  `script` text COLLATE utf8mb4_unicode_ci COMMENT 'Groovy动态脚本(reactiveChoice使用)',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for jenkins_env_var
-- ----------------------------
DROP TABLE IF EXISTS `jenkins_env_var`;
CREATE TABLE `jenkins_env_var` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `env_group` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'global' COMMENT '分组/环境(global/dev/prod)',
  `key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '环境变量Key',
  `value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '环境变量Value',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for jenkins_instances
-- ----------------------------
DROP TABLE IF EXISTS `jenkins_instances`;
CREATE TABLE `jenkins_instances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jenkins实例名称',
  `url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jenkins URL地址',
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `api_token` text COLLATE utf8mb4_unicode_ci COMMENT 'API Token或密码',
  `env` longtext COLLATE utf8mb4_unicode_ci COMMENT '环境信息 prod|stage|test',
  `action_timeout_seconds` bigint DEFAULT NULL COMMENT '超时秒数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_jenkins_instances_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for jenkins_job
-- ----------------------------
DROP TABLE IF EXISTS `jenkins_job`;
CREATE TABLE `jenkins_job` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `instance_id` bigint unsigned DEFAULT NULL COMMENT '关联实例ID',
  `deploy_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部署方式(主机IP、容器集群)(构建时传参)',
  `deploy_env` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部署环境(dev|test|stage|uat|pre|prod)',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务名(与Jenkins中的名称一致,创建Job时用)',
  `project_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称(对应的是GIT仓库的group名称,创建Job时用)',
  `git_repo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'GIT仓库克隆地址(构建时传参)',
  `git_branch` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'main' COMMENT 'GIT分支(构建时传参)',
  `url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '该job的jenkins地址',
  `lang` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'Java' COMMENT '该job是什么技术栈',
  `log_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '二进制进程日志绝对路径',
  `count` bigint DEFAULT '0' COMMENT '最后构建号',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'NOT_BUILT' COMMENT '同步jenkins真实的job状态',
  `create_user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `enable_delete` tinyint NOT NULL DEFAULT '2' COMMENT '删除控制: 1-开启删除 2-禁止删除 默认为2',
  `last_build_time` datetime DEFAULT NULL COMMENT '最后构建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inst_job_proj` (`instance_id`,`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for jenkins_pipeline_config
-- ----------------------------
DROP TABLE IF EXISTS `jenkins_pipeline_config`;
CREATE TABLE `jenkins_pipeline_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流水线配置名称',
  `lang` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'Vue/TS' COMMENT '适用语言(Vue/TS/Java/Go/Python)',
  `agent_node` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'master' COMMENT '构建节点',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述说明',
  `stage_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '关联Stage的ID列表与顺序',
  `env_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '关联环境变量ID列表',
  `param_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '关联构建参数ID列表',
  `pipeline_script` text COLLATE utf8mb4_unicode_ci COMMENT '拼接生成的Groovy脚本',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for jenkins_stage
-- ----------------------------
DROP TABLE IF EXISTS `jenkins_stage`;
CREATE TABLE `jenkins_stage` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Stage名称',
  `code_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '阶段唯一标识',
  `category` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'general' COMMENT '分类(frontend/backend/general)',
  `agent_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'none' COMMENT 'Agent类型(none/label/docker)',
  `docker_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Docker镜像',
  `when_expr` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发条件表达式',
  `steps` text COLLATE utf8mb4_unicode_ci COMMENT 'Groovy 步骤脚本指令',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述说明',
  `order_no` bigint DEFAULT '0' COMMENT '排序',
  `enabled` tinyint(1) DEFAULT '1' COMMENT '默认是否启用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_jenkins_stage_code_key` (`code_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for job_results
-- ----------------------------
DROP TABLE IF EXISTS `job_results`;
CREATE TABLE `job_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `job_id` bigint unsigned DEFAULT NULL COMMENT 'ip',
  `status` longtext COLLATE utf8mb4_unicode_ci COMMENT '当前状态',
  `stdout` longtext COLLATE utf8mb4_unicode_ci COMMENT '标准输出',
  `stderr` longtext COLLATE utf8mb4_unicode_ci COMMENT '标准错误',
  `host_ip` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主机IP',
  `host_name` longtext COLLATE utf8mb4_unicode_ci COMMENT '主机名',
  PRIMARY KEY (`id`),
  UNIQUE KEY `jid_hostip` (`job_id`,`host_ip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for job_scripts
-- ----------------------------
DROP TABLE IF EXISTS `job_scripts`;
CREATE TABLE `job_scripts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务脚本名称',
  `lang` longtext COLLATE utf8mb4_unicode_ci,
  `user_id` bigint unsigned DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '脚本原始内容',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_job_scripts_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for job_tasks
-- ----------------------------
DROP TABLE IF EXISTS `job_tasks`;
CREATE TABLE `job_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `title` longtext COLLATE utf8mb4_unicode_ci COMMENT '中文名称',
  `account` longtext COLLATE utf8mb4_unicode_ci COMMENT '执行任务的账号',
  `args` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行任务的参数',
  `script_content` longtext COLLATE utf8mb4_unicode_ci COMMENT '脚本内容 来源2种：01当场写的 02从script表中获取',
  `exec_timeout_seconds` bigint DEFAULT NULL COMMENT '任务执行超时时间',
  `batch_size` bigint DEFAULT NULL COMMENT '机器并发执行数量',
  `on_error_strategy` longtext COLLATE utf8mb4_unicode_ci COMMENT '遇到某些机器出错后的策略，忽略执行完 | 遇到错误停止 | 遇到错误暂停',
  `tree_node_id` bigint unsigned DEFAULT NULL COMMENT '关联的服务树节点',
  `hosts_raw` text COLLATE utf8mb4_unicode_ci COMMENT '机器的IP列表',
  `scheduled_hosts` text COLLATE utf8mb4_unicode_ci COMMENT '已经下发的机器IP列表 并发或者暂停使用',
  `status` longtext COLLATE utf8mb4_unicode_ci COMMENT '当前执行状态',
  `action` longtext COLLATE utf8mb4_unicode_ci COMMENT '当前执行动作',
  `user_id` bigint unsigned DEFAULT NULL,
  `actual_flow_data` text COLLATE utf8mb4_unicode_ci COMMENT '任务执行的状态记录 结果(JSON串)',
  `lang` longtext COLLATE utf8mb4_unicode_ci COMMENT '脚本语言(shell/python/ansible)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_apps
-- ----------------------------
DROP TABLE IF EXISTS `k8s_apps`;
CREATE TABLE `k8s_apps` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用英文名称',
  `k8s_project_id` bigint unsigned DEFAULT NULL COMMENT '属于哪个项目 一对多外键',
  `tree_node_id` bigint unsigned DEFAULT NULL COMMENT '绑定到哪个节点 面向第四层级',
  `user_id` bigint unsigned DEFAULT NULL,
  `namespace` longtext COLLATE utf8mb4_unicode_ci,
  `envs` longtext COLLATE utf8mb4_unicode_ci COMMENT '环境变量组 k=v',
  `labels` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签组 k=v',
  `commands` longtext COLLATE utf8mb4_unicode_ci COMMENT '启动命令组',
  `cpu_request` longtext COLLATE utf8mb4_unicode_ci,
  `cpu_limit` longtext COLLATE utf8mb4_unicode_ci,
  `memory_request` longtext COLLATE utf8mb4_unicode_ci,
  `memory_limit` longtext COLLATE utf8mb4_unicode_ci,
  `args` longtext COLLATE utf8mb4_unicode_ci COMMENT '启动命令参数组 空格分隔',
  `volume_json` text COLLATE utf8mb4_unicode_ci COMMENT '卷和挂载配置',
  `port_json` text COLLATE utf8mb4_unicode_ci COMMENT '容器和svc端口配置',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_project_app_name` (`name`,`k8s_project_id`),
  KEY `fk_k8s_projects_k8s_apps` (`k8s_project_id`),
  CONSTRAINT `fk_k8s_projects_k8s_apps` FOREIGN KEY (`k8s_project_id`) REFERENCES `k8s_projects` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_clusters
-- ----------------------------
DROP TABLE IF EXISTS `k8s_clusters`;
CREATE TABLE `k8s_clusters` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'k8s集群英文名称',
  `name_zh` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'k8s集群中文名称',
  `user_id` bigint unsigned DEFAULT NULL,
  `env` longtext COLLATE utf8mb4_unicode_ci COMMENT '集群环境信息 prod|stage|test',
  `version` longtext COLLATE utf8mb4_unicode_ci COMMENT '集群版本',
  `api_server_addr` longtext COLLATE utf8mb4_unicode_ci COMMENT 'apiServer地址',
  `kube_config_content` longtext COLLATE utf8mb4_unicode_ci COMMENT 'kubeconfig配置文件',
  `action_timeout_seconds` bigint DEFAULT NULL COMMENT '超时时间秒数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_k8s_clusters_name` (`name`),
  UNIQUE KEY `idx_k8s_clusters_name_zh` (`name_zh`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_instances
-- ----------------------------
DROP TABLE IF EXISTS `k8s_instances`;
CREATE TABLE `k8s_instances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实例英文名称',
  `user_id` bigint unsigned DEFAULT NULL,
  `envs` longtext COLLATE utf8mb4_unicode_ci COMMENT '环境变量组 k=v',
  `labels` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签组 k=v',
  `commands` longtext COLLATE utf8mb4_unicode_ci COMMENT '启动命令组',
  `cpu_request` longtext COLLATE utf8mb4_unicode_ci,
  `cpu_limit` longtext COLLATE utf8mb4_unicode_ci,
  `memory_request` longtext COLLATE utf8mb4_unicode_ci,
  `memory_limit` longtext COLLATE utf8mb4_unicode_ci,
  `args` longtext COLLATE utf8mb4_unicode_ci COMMENT '启动命令参数组 空格分隔',
  `volume_json` text COLLATE utf8mb4_unicode_ci COMMENT '卷和挂载配置',
  `port_json` text COLLATE utf8mb4_unicode_ci COMMENT '容器和svc端口配置',
  `image` longtext COLLATE utf8mb4_unicode_ci,
  `replicas` bigint DEFAULT NULL,
  `workload_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Deployment' COMMENT '工作负载类型',
  `env` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'prod' COMMENT '环境',
  `enable_svc` tinyint(1) DEFAULT '0' COMMENT '开启Service',
  `svc_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'ClusterIP' COMMENT 'Service类型',
  `enable_ingress` tinyint(1) DEFAULT '0' COMMENT '开启Ingress',
  `ingress_host` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ingress域名',
  `config_map_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联ConfigMap',
  `secret_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联Secret',
  `k8s_app_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_app_instance_name` (`name`),
  KEY `fk_k8s_apps_k8s_instances` (`k8s_app_id`),
  CONSTRAINT `fk_k8s_apps_k8s_instances` FOREIGN KEY (`k8s_app_id`) REFERENCES `k8s_apps` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_projects
-- ----------------------------
DROP TABLE IF EXISTS `k8s_projects`;
CREATE TABLE `k8s_projects` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目英文名称',
  `name_zh` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目中文名称',
  `cluster` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目绑定的集群名称',
  `tree_node_id` bigint unsigned DEFAULT NULL COMMENT '绑定到哪个节点 面向第三层级',
  `user_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cluster_name` (`name`,`cluster`),
  UNIQUE KEY `idx_cluster_name_zh` (`name_zh`,`cluster`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_yaml_task_logs
-- ----------------------------
DROP TABLE IF EXISTS `k8s_yaml_task_logs`;
CREATE TABLE `k8s_yaml_task_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `task_id` bigint unsigned DEFAULT NULL COMMENT 'YAML任务ID',
  `task_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务名称',
  `cluster_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标集群',
  `template_id` bigint unsigned DEFAULT NULL COMMENT '模板ID',
  `yaml_content` text COLLATE utf8mb4_unicode_ci COMMENT '应用时的实际YAML内容',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行状态 SUCCESS/FAILED',
  `err_msg` text COLLATE utf8mb4_unicode_ci COMMENT '错误堆栈信息',
  `user_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_yaml_tasks
-- ----------------------------
DROP TABLE IF EXISTS `k8s_yaml_tasks`;
CREATE TABLE `k8s_yaml_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'yaml任务名称',
  `user_id` bigint unsigned DEFAULT NULL,
  `template_id` bigint unsigned DEFAULT NULL,
  `cluster_name` longtext COLLATE utf8mb4_unicode_ci,
  `variables` text COLLATE utf8mb4_unicode_ci COMMENT 'yaml环境变量 k=v',
  `status` longtext COLLATE utf8mb4_unicode_ci COMMENT '当前状态',
  `apply_result` longtext COLLATE utf8mb4_unicode_ci COMMENT 'apply后的结果返回值',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_k8s_yaml_tasks_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for k8s_yaml_templates
-- ----------------------------
DROP TABLE IF EXISTS `k8s_yaml_templates`;
CREATE TABLE `k8s_yaml_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'yaml模板名称',
