-- ----------------------------
-- Table structure for monitor_alert_manager_events
-- ----------------------------
DROP TABLE IF EXISTS `monitor_alert_manager_events`;
CREATE TABLE `monitor_alert_manager_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `alert_name` longtext COLLATE utf8mb4_unicode_ci,
  `finger_print` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '告警unique id eventId',
  `status` longtext COLLATE utf8mb4_unicode_ci COMMENT '告警状态： 告警中|已屏蔽|已认领|已恢复',
  `rule_id` bigint unsigned DEFAULT NULL,
  `send_group_id` bigint unsigned DEFAULT NULL,
  `event_times` bigint DEFAULT NULL COMMENT '触发次数',
  `silence_id` longtext COLLATE utf8mb4_unicode_ci COMMENT 'alertmanager返回的静默id',
  `unsilenced_at` datetime(3) DEFAULT NULL COMMENT '最近一次解除屏蔽的时间',
  `re_ling_user_id` bigint unsigned DEFAULT NULL COMMENT '是谁认领了告警',
  `labels` longtext COLLATE utf8mb4_unicode_ci COMMENT ' 标签组 k=v',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_monitor_alert_manager_events_finger_print` (`finger_print`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for monitor_alert_manager_pools
-- ----------------------------
