  `alert_manager_instances` longtext COLLATE utf8mb4_unicode_ci,
  `user_id` bigint unsigned DEFAULT NULL,
  `enable` bigint DEFAULT NULL COMMENT '是否被开启 1正常 2禁用',
  `resolve_timeout` longtext COLLATE utf8mb4_unicode_ci COMMENT '默认恢复时间',
  `group_wait` longtext COLLATE utf8mb4_unicode_ci COMMENT '默认分组第一次等待时间',
  `group_interval` longtext COLLATE utf8mb4_unicode_ci COMMENT '默认分组间隔',
  `repeat_interval` longtext COLLATE utf8mb4_unicode_ci COMMENT '默认重复发送间隔',
  `group_by` longtext COLLATE utf8mb4_unicode_ci COMMENT '分组标签',
  `receiver` longtext COLLATE utf8mb4_unicode_ci COMMENT '兜底接收者',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_monitor_alert_manager_pools_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
