  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送组英文名称',
  `name_zh` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送组中文名称',
  `enable` bigint DEFAULT NULL COMMENT '是否被开启 1正常 2禁用',
  `user_id` bigint unsigned DEFAULT NULL,
  `pool_id` bigint unsigned DEFAULT NULL COMMENT '关联哪个alertManager实例',
  `on_duty_group_id` bigint unsigned DEFAULT NULL COMMENT '值班表 在im中发到群组里at值班人或者私聊发送给值班人',
  `fei_shu_qun_robot_token` longtext COLLATE utf8mb4_unicode_ci COMMENT 'im飞书自定义机器人token',
