  `upgrade_minutes` bigint DEFAULT NULL COMMENT '告警多久未恢复就升级',
  `need_upgrade` bigint DEFAULT NULL COMMENT '是否告警升级 1=升级 2=不升级',
  `tree_node_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '如果使用了服务树接口 通过树id获取ip列表',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_monitor_alert_manager_send_groups_name` (`name`),
  UNIQUE KEY `idx_monitor_alert_manager_send_groups_name_zh` (`name_zh`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

