  `pool_id` bigint unsigned DEFAULT NULL COMMENT '关联哪个prometheus实例',
  `send_group_id` bigint DEFAULT NULL,
  `tree_node_id` bigint unsigned DEFAULT NULL COMMENT '绑定到哪个节点',
  `enable` bigint DEFAULT NULL COMMENT '是否被开启 1正常 2禁用',
