  `labels` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签组 k=v ,severity=critical',
  `annotations` longtext COLLATE utf8mb4_unicode_ci COMMENT '注解 k=v ,summary=xxx,description=xxx',
  `tree_node_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '如果使用了服务树接口 通过树id获取ip列表',
  PRIMARY KEY (`id`)
