-- ----------------------------
-- Table structure for monitor_prom_scrape_jobs
-- ----------------------------
DROP TABLE IF EXISTS `monitor_prom_scrape_jobs`;
CREATE TABLE `monitor_prom_scrape_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采集任务名称',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '创建人ID',
  `enable` bigint DEFAULT NULL COMMENT '是否被开启 1正常 2禁用',
  `service_discovery_type` longtext COLLATE utf8mb4_unicode_ci COMMENT 'k8s or tree-http',
  `metrics_path` longtext COLLATE utf8mb4_unicode_ci,
  `scheme` longtext COLLATE utf8mb4_unicode_ci,
  `scrape_interval` bigint DEFAULT NULL COMMENT '采集间隔',
  `scrape_timeout` bigint DEFAULT NULL COMMENT '采集超时时间',
  `pool_id` bigint unsigned DEFAULT NULL,
  `relabel_configs_yaml_string` text COLLATE utf8mb4_unicode_ci COMMENT 'yaml字符串',
  `port` bigint DEFAULT NULL COMMENT '用虚拟机类型的时候 服务树服务发现接口类型 需要传port',
  `refresh_interval` bigint DEFAULT NULL COMMENT 'sd发现刷新间隔',
  `tree_node_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '如果使用了服务树接口 通过树id获取ip列表',
  `blackbox_address` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'blackbox-exporter地址',
  `probe_module` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'blackbox探测模块',
  `api_server` longtext COLLATE utf8mb4_unicode_ci COMMENT ' apiServer地址',
  `kube_config_file_path` longtext COLLATE utf8mb4_unicode_ci COMMENT ' kubeconfig文件路径',
  `tls_ca_file_path` longtext COLLATE utf8mb4_unicode_ci COMMENT ' kubelet client CA文件路径',
  `tls_ca_content` longtext COLLATE utf8mb4_unicode_ci COMMENT ' kubelet client CA文件内容',
  `bearer_token` longtext COLLATE utf8mb4_unicode_ci COMMENT ' SA鉴权token',
  `bearer_token_file` longtext COLLATE utf8mb4_unicode_ci COMMENT ' SA鉴权token文件',
  `kubernetes_sd_role` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for monitor_prom_scrape_pools
-- ----------------------------
DROP TABLE IF EXISTS `monitor_prom_scrape_pools`;
CREATE TABLE `monitor_prom_scrape_pools` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采集池名称',
  `prometheus_instances` longtext COLLATE utf8mb4_unicode_ci,
  `user_id` bigint unsigned DEFAULT NULL COMMENT '创建人ID',
  `scrape_interval` bigint DEFAULT NULL COMMENT '采集间隔',
  `scrape_timeout` bigint DEFAULT NULL COMMENT '采集超时时间',
  `external_labels` longtext COLLATE utf8mb4_unicode_ci COMMENT 'remote_write的时候添加的标签组 key=v',
  `supper_alert` bigint DEFAULT NULL COMMENT '是否支持告警 1支持 2不支持',
  `supper_record` bigint DEFAULT NULL COMMENT '是否支持record 1支持 2不支持',
  `remote_read_url` longtext COLLATE utf8mb4_unicode_ci COMMENT '远程读取的地址',
  `alert_manager_url` longtext COLLATE utf8mb4_unicode_ci COMMENT 'alertManager地址',
  `rule_file_path` longtext COLLATE utf8mb4_unicode_ci COMMENT 'rule告警规则文件路径',
  `record_file_path` longtext COLLATE utf8mb4_unicode_ci COMMENT 'record预聚合的文件路径',
  `remote_write_url` longtext COLLATE utf8mb4_unicode_ci COMMENT 'tsdb远程写入的地址',
  `remote_timeout_seconds` bigint DEFAULT NULL COMMENT 'tsdb远程写入的超时时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_monitor_prom_scrape_pools_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for resource_dns
-- ----------------------------
DROP TABLE IF EXISTS `resource_dns`;
CREATE TABLE `resource_dns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `vendor` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `domain` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `value` longtext COLLATE utf8mb4_unicode_ci,
  `ttl` bigint DEFAULT NULL,
  `hash` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `associated_instance_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ecs_instance_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_resource_dns_vendor` (`vendor`),
  KEY `idx_resource_dns_domain` (`domain`),
  KEY `idx_resource_dns_name` (`name`),
  KEY `idx_resource_dns_type` (`type`),
  KEY `idx_resource_dns_hash` (`hash`),
  KEY `idx_resource_dns_associated_instance_id` (`associated_instance_id`),
  KEY `idx_resource_dns_ecs_instance_id` (`ecs_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for resource_ecs
-- ----------------------------
DROP TABLE IF EXISTS `resource_ecs`;
CREATE TABLE `resource_ecs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `hash` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '增量更新唯一标识',
  `vendor` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '云厂商 阿里 华为 aws',
  `zone_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例可用区',
  `account_name` longtext COLLATE utf8mb4_unicode_ci,
  `tags` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签集合[k1=v1,k2=v2]',
  `env` longtext COLLATE utf8mb4_unicode_ci COMMENT '环境标识：dev开发 |test测试 |stage预发 |press压测 | prod生产',
  `instance_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实例id',
  `instance_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实例名称，支持通配符*进行模糊搜索',
  `instance_type` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例规格',
  `vpc_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '专有网络VPC ID',
  `vm_type` bigint DEFAULT '1' COMMENT '资源种类: 1=云虚拟机, 2=物理机, 3=容器',
  `os_type` longtext COLLATE utf8mb4_unicode_ci COMMENT '操作系统类型',
  `status` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例状态。取值范围：Pending创建中| Running运行中 |Starting启动中 |Stopping停止中|Stopped已停止。',
  `cpu` bigint DEFAULT NULL COMMENT 'vCPU数',
  `memory` bigint DEFAULT NULL COMMENT '内存大小 单位为MiB',
  `os_name` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例操作系统名称',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例操作系统名称',
  `image_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '镜像模板',
  `host_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主机名',
  `security_group_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '安全组id',
  `private_ip_address` longtext COLLATE utf8mb4_unicode_ci COMMENT '私有 IP 地址列表：[172.17.**.**]',
  `public_ip_addresses` longtext COLLATE utf8mb4_unicode_ci COMMENT '公网 IP 地址列表：[1.1.1.1]',
  `network_interfaces` longtext COLLATE utf8mb4_unicode_ci COMMENT '弹性网卡id集合[cni-xx1,cni-xx2]',
  `disk_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '云硬盘或本地盘id',
  `start_time` datetime(3) DEFAULT NULL COMMENT '实例最近一次的启动时间。以 ISO 8601 为标准，并使用 UTC+0 时间，格式为 yyyy-MM-ddTHH:mmZ',
  `creation_time` datetime(3) DEFAULT NULL COMMENT '实例创建时间。以 ISO 8601 为标准，并使用 UTC+0 时间，格式为 yyyy-MM-ddTHH:mmZ',
  `expired_time` datetime(3) DEFAULT NULL COMMENT '过期时间。以 ISO 8601 为标准，并使用 UTC+0 时间，格式为 yyyy-MM-ddTHH:mmZ',
  `auto_release_time` datetime(3) DEFAULT NULL,
  `last_heartbeat_time` datetime(3) DEFAULT NULL COMMENT 'Agent最近一次心跳时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_resource_ecs_hash` (`hash`),
  UNIQUE KEY `idx_resource_ecs_instance_id` (`instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for resource_elbs
-- ----------------------------
DROP TABLE IF EXISTS `resource_elbs`;
CREATE TABLE `resource_elbs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `hash` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '增量更新唯一标识',
  `vendor` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '云厂商 阿里 华为 aws',
  `zone_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例可用区',
  `account_name` longtext COLLATE utf8mb4_unicode_ci,
  `tags` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签集合[k1=v1,k2=v2]',
  `env` longtext COLLATE utf8mb4_unicode_ci COMMENT '环境标识：dev开发 |test测试 |stage预发 |press压测 | prod生产',
  `load_balancer_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实例id',
  `load_balancer_name` longtext COLLATE utf8mb4_unicode_ci,
  `load_balancer_type` longtext COLLATE utf8mb4_unicode_ci COMMENT 'LB实例类型：alb、nlb、clb',
  `bandwidth_capacity` bigint DEFAULT NULL COMMENT '带宽包上限',
  `vpc_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '专有网络VPC ID',
  `address_type` longtext COLLATE utf8mb4_unicode_ci COMMENT '网络类型(internet公网/intranet私网)',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实例状态(如active/inactive)',
  `private_ip_address` longtext COLLATE utf8mb4_unicode_ci COMMENT '私有 IP 地址列表：[172.17.**.**]',
  `public_ip_addresses` longtext COLLATE utf8mb4_unicode_ci COMMENT '公网 IP 地址列表：[1.1.1.1]',
  `security_group_ids` longtext COLLATE utf8mb4_unicode_ci COMMENT '安全组id',
  `dns_name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'DNS解析地址',
  `creation_time` datetime(3) DEFAULT NULL COMMENT '实例创建时间。以 ISO 8601 为标准，并使用 UTC+0 时间，格式为 yyyy-MM-ddTHH:mmZ',
  `bandwidth_package_id` bigint DEFAULT NULL COMMENT '绑定的带宽包',
  `cross_zone_enabled` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_resource_elbs_hash` (`hash`),
  UNIQUE KEY `idx_resource_elbs_load_balancer_id` (`load_balancer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for resource_rds
-- ----------------------------
DROP TABLE IF EXISTS `resource_rds`;
CREATE TABLE `resource_rds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `hash` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '增量更新唯一标识',
  `vendor` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '云厂商 阿里 华为 aws',
  `zone_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例可用区',
  `account_name` longtext COLLATE utf8mb4_unicode_ci,
  `tags` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签集合[k1=v1,k2=v2]',
  `env` longtext COLLATE utf8mb4_unicode_ci COMMENT '环境标识：dev开发 |test测试 |stage预发 |press压测 | prod生产',
  `engine` longtext COLLATE utf8mb4_unicode_ci COMMENT '数据库类型 MySQL mariaDB postgresql redis',
  `db_instance_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例ID',
  `name` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例名称/别名',
  `db_instance_net_type` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例网络类型, Internet:外网 Intranet:内网连接',
  `db_instance_class` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例规格,rds.mys2.small',
  `db_instance_type` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例类型是否主备。Primary|Readonly|Guard|Temp',
  `engine_version` longtext COLLATE utf8mb4_unicode_ci COMMENT '数据库版本',
  `pay_type` longtext COLLATE utf8mb4_unicode_ci COMMENT '付费类型 包年包月 | 按量付费',
  `db_instance_status` longtext COLLATE utf8mb4_unicode_ci COMMENT '实例状态，running | stop',
  `vpc_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '专有网络VPC ID',
  `creation_time` datetime(3) DEFAULT NULL COMMENT '实例创建时间。以 ISO 8601 为标准，并使用 UTC+0 时间，格式为 yyyy-MM-ddTHH:mmZ',
  `expired_time` datetime(3) DEFAULT NULL COMMENT '过期时间。以 ISO 8601 为标准，并使用 UTC+0 时间，格式为 yyyy-MM-ddTHH:mmZ',
  `host` longtext COLLATE utf8mb4_unicode_ci COMMENT '连接地址/IP',
  `port` bigint DEFAULT NULL COMMENT '连接端口',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_resource_rds_hash` (`hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

