-- ----------------------------
-- Table structure for stree_nodes
-- ----------------------------
DROP TABLE IF EXISTS `stree_nodes`;
CREATE TABLE `stree_nodes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `title` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称',
  `pid` bigint unsigned DEFAULT NULL COMMENT '父级ID 树用的',
  `level` bigint DEFAULT NULL COMMENT '层级',
  `is_leaf` tinyint(1) DEFAULT NULL COMMENT '类型 0=否 1=是',
  `desc` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_stree_nodes_title` (`title`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_apis
-- ----------------------------
DROP TABLE IF EXISTS `system_apis`;
CREATE TABLE `system_apis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `type` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型 0=父级 1=子级',
  `path` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路由路径',
  `method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'http请求方法',
  `pid` bigint DEFAULT NULL COMMENT '父级ID 为了给树用的',
  `title` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_system_apis_title` (`title`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_audit_logs
-- ----------------------------
DROP TABLE IF EXISTS `system_audit_logs`;
CREATE TABLE `system_audit_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人账号',
  `real_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人昵称',
  `module` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '功能模块',
  `action` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作类型',
  `method` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求方法',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求路径',
  `ip` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作者IP',
  `status` bigint DEFAULT NULL COMMENT 'HTTP状态码',
  `latency` bigint DEFAULT NULL COMMENT '耗时(毫秒)',
  `req_body` longtext COLLATE utf8mb4_unicode_ci COMMENT '请求报文',
  `resp_message` text COLLATE utf8mb4_unicode_ci COMMENT '响应摘要',
  PRIMARY KEY (`id`),
  KEY `idx_system_audit_logs_user_id` (`user_id`),
  KEY `idx_system_audit_logs_username` (`username`),
  KEY `idx_system_audit_logs_module` (`module`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_login_logs
-- ----------------------------
DROP TABLE IF EXISTS `system_login_logs`;
CREATE TABLE `system_login_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL COMMENT '用户ID',
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录账号',
  `real_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户姓名',
  `login_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录类型(密码登录/OIDC单点/钉钉扫码/退出登录/强退)',
  `ip` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录IP',
  `os` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作系统',
  `browser` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '浏览器',
  `status` bigint DEFAULT NULL COMMENT '登录状态(1:成功, 0:失败)',
  `message` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '提示信息',
  PRIMARY KEY (`id`),
  KEY `idx_system_login_logs_user_id` (`user_id`),
  KEY `idx_system_login_logs_username` (`username`),
  KEY `idx_system_login_logs_login_type` (`login_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_menus
-- ----------------------------
DROP TABLE IF EXISTS `system_menus`;
CREATE TABLE `system_menus` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '英文名称',
  `title` longtext COLLATE utf8mb4_unicode_ci COMMENT '中文名称',
  `pid` bigint DEFAULT NULL COMMENT '父级的ID',
  `parent_menu` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父级的菜单',
  `icon` longtext COLLATE utf8mb4_unicode_ci COMMENT '图标',
  `type` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型 0=目录 1=子菜单',
  `show` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否显示 0=禁用 1=启用',
  `order_no` bigint DEFAULT NULL COMMENT '排序',
  `component` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端组件 菜单就是LAYOUT',
  `redirect` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示路径',
  `path` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路由路径',
  `remark` longtext COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `home_path` longtext COLLATE utf8mb4_unicode_ci COMMENT '登录后的默认首页',
  `status` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '菜单是否开启 0禁用 1启用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_system_menus_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_role_apis
-- ----------------------------
DROP TABLE IF EXISTS `system_role_apis`;
CREATE TABLE `system_role_apis` (
  `system_api_id` bigint unsigned NOT NULL,
  `system_role_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`system_api_id`,`system_role_id`),
  KEY `fk_system_role_apis_system_role` (`system_role_id`),
  CONSTRAINT `fk_system_role_apis_system_api` FOREIGN KEY (`system_api_id`) REFERENCES `system_apis` (`id`),
  CONSTRAINT `fk_system_role_apis_system_role` FOREIGN KEY (`system_role_id`) REFERENCES `system_roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

