DROP TABLE IF EXISTS `system_role_menus`;
CREATE TABLE `system_role_menus` (
  `system_menu_id` bigint unsigned NOT NULL,
  `system_role_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`system_menu_id`,`system_role_id`),
  KEY `fk_system_role_menus_system_role` (`system_role_id`),
  CONSTRAINT `fk_system_role_menus_system_menu` FOREIGN KEY (`system_menu_id`) REFERENCES `system_menus` (`id`),
  CONSTRAINT `fk_system_role_menus_system_role` FOREIGN KEY (`system_role_id`) REFERENCES `system_roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_roles
-- ----------------------------
DROP TABLE IF EXISTS `system_roles`;
CREATE TABLE `system_roles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `order_no` bigint DEFAULT NULL COMMENT '排序',
  `role_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色中文名称',
  `role_value` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色值',
  `remark` longtext COLLATE utf8mb4_unicode_ci COMMENT '用户描述',
  `status` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '角色是否开启 1正常 2冻结',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_system_roles_role_name` (`role_name`),
  UNIQUE KEY `idx_system_roles_role_value` (`role_value`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_setting
-- ----------------------------
