CREATE TABLE `system_setting` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `watermark_enabled` tinyint(1) DEFAULT NULL,
  `watermark_text` longtext COLLATE utf8mb4_unicode_ci,
  `upgrade_prompt_enabled` tinyint(1) DEFAULT NULL,
  `upgrade_prompt_timing` longtext COLLATE utf8mb4_unicode_ci,
  `upgrade_prompt_title` longtext COLLATE utf8mb4_unicode_ci,
  `upgrade_prompt_version` longtext COLLATE utf8mb4_unicode_ci,
  `upgrade_prompt_content` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_system_setting_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for system_user_roles
-- ----------------------------
DROP TABLE IF EXISTS `system_user_roles`;
CREATE TABLE `system_user_roles` (
  `system_role_id` bigint unsigned NOT NULL,
  `system_user_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`system_role_id`,`system_user_id`),
  KEY `fk_system_user_roles_system_user` (`system_user_id`),
  CONSTRAINT `fk_system_user_roles_system_role` FOREIGN KEY (`system_role_id`) REFERENCES `system_roles` (`id`),
  CONSTRAINT `fk_system_user_roles_system_user` FOREIGN KEY (`system_user_id`) REFERENCES `system_users` (`id`)
