-- ----------------------------
-- Table structure for system_users
-- ----------------------------
DROP TABLE IF EXISTS `system_users`;
CREATE TABLE `system_users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户登录名',
  `password` longtext COLLATE utf8mb4_unicode_ci COMMENT '用户登录密码',
  `email` longtext COLLATE utf8mb4_unicode_ci COMMENT '用户邮箱',
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户手机号',
  `real_name` longtext COLLATE utf8mb4_unicode_ci COMMENT '用户昵称',
  `avatar` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户头像URL',
  `desc` longtext COLLATE utf8mb4_unicode_ci COMMENT '用户描述',
  `fei_shu_user_id` longtext COLLATE utf8mb4_unicode_ci COMMENT '飞书userid',
  `ding_talk_user_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '钉钉员工userid/工号',
  `ding_talk_union_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '钉钉全局唯一unionid',
  `home_path` longtext COLLATE utf8mb4_unicode_ci COMMENT '登录后跳转地址',
  `enable` bigint DEFAULT '1' COMMENT '用户是否被冻结 1正常 2冻结',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_system_users_username` (`username`),
  KEY `idx_system_users_ding_talk_user_id` (`ding_talk_user_id`),
  KEY `idx_system_users_ding_talk_union_id` (`ding_talk_union_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

