  `type` longtext COLLATE utf8mb4_unicode_ci COMMENT ' 起始节点 审批节点 执行节点 结束节点',
  `define_user_or_group` longtext COLLATE utf8mb4_unicode_ci COMMENT '期望的人或组 userName or RoleName',
  PRIMARY KEY (`id`),
