  CONSTRAINT `fk_work_order_processes_flow_nodes` FOREIGN KEY (`process_id`) REFERENCES `work_order_processes` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

