-- ----------------------------
-- Table structure for work_order_instances
-- ----------------------------
DROP TABLE IF EXISTS `work_order_instances`;
CREATE TABLE `work_order_instances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单实例名称',
  `actual_api_json_data` text COLLATE utf8mb4_unicode_ci COMMENT '用户填写的动态表单数据(JSON串)',
  `desire_finish_time` datetime DEFAULT NULL COMMENT '期望完成时间',
  `template_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '审批中' COMMENT '工单状态(审批中/已通过/已驳回/已取消)',
  `current_flow_node` longtext COLLATE utf8mb4_unicode_ci COMMENT '当前执行到哪个节点',
  `actual_flow_data` text COLLATE utf8mb4_unicode_ci COMMENT '真实执行的历史记录 审批结果(JSON串)',
  `final_run_data` text COLLATE utf8mb4_unicode_ci COMMENT '最终的执行结果',
  `comments` text COLLATE utf8mb4_unicode_ci COMMENT '用户评论(JSON串)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_work_order_instances_title` (`title`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for work_order_processes
-- ----------------------------
DROP TABLE IF EXISTS `work_order_processes`;
CREATE TABLE `work_order_processes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程名称',
  `user_id` bigint unsigned DEFAULT NULL,
  `status` longtext COLLATE utf8mb4_unicode_ci COMMENT '执行中 | 已完成 | 已拒绝 | 已驳回',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_work_order_processes_name` (`name`),
  KEY `fk_system_users_processes` (`user_id`),
  CONSTRAINT `fk_system_users_processes` FOREIGN KEY (`user_id`) REFERENCES `system_users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for work_order_templates
-- ----------------------------
DROP TABLE IF EXISTS `work_order_templates`;
CREATE TABLE `work_order_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单模板名称',
  `user_id` bigint unsigned DEFAULT NULL,
  `form_design_id` bigint unsigned DEFAULT NULL,
  `process_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_work_order_templates_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for workorder_notify_status
-- ----------------------------
DROP TABLE IF EXISTS `workorder_notify_status`;
CREATE TABLE `workorder_notify_status` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notice_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint NOT NULL COMMENT '''1:已读, 2:已清空''',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_notice` (`user_name`,`notice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

