('4', '2026-09-24 14:21:30.361', '2026-09-24 14:21:30.361', 'yaml-template-3', '1', 'apiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata:\n  name: VAR_NGX_DEP_NAME\nspec:\n  ingressClassName: \"nginx\"\n  rules:\n  - host: books.xxx.me\n    http:\n      paths:\n      - path: /\n        pathType: Prefix\n        backend:\n          service:\n            name: guestbook-svc    # guestbook的service名称\n            port:\n              name: http  # 可以写\n              #number: 80'),
