('1', '2026-09-24 14:21:23.271', '2026-09-24 14:21:23.271', '流水线开通表单', '1', '0', '{\"schemas\":[{\"component\":\"Divider\",\"label\":\"1. 代码仓库配置\",\"icon\":\"radix-icons:divider-horizontal\",\"field\":\"_divider_1\",\"colProps\":{\"span\":24},\"componentProps\":{\"orientation\":\"center\",\"dashed\":true,\"plain\":false},\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"key\":\"_divider_1\"},{\"component\":\"ApiSelect\",\"label\":\"GIT仓库\",\"icon\":\"ant-design:api-outlined\",\"field\":\"git_repo\",\"required\":true,\"colProps\":{\"span\":24},\"componentProps\":{\"api\":\"/api/code/getCodeGitRepoList\",\"resultField\":\"items\",\"labelField\":\"fullName\",\"valueField\":\"cloneUrlSsh\",\"optionLabelProp\":\"value\",\"placeholder\":\"下拉选择 GIT 仓库地址...\"},\"key\":\"_api_select_2\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"link\":[]},{\"component\":\"ApiSelect\",\"label\":\"GIT分支\",\"icon\":\"ant-design:branches-outlined\",\"field\":\"git_branch\",\"required\":true,\"colProps\":{\"span\":24},\"componentProps\":{\"api\":\"/api/code/getRepoBranches\",\"labelField\":\"name\",\"valueField\":\"name\",\"params\":{\"fullName\":\"$git_repo\"},\"placeholder\":\"选定 GIT 仓库后自动获取真实分支...\"},\"link\":[\"git_repo\"],\"key\":\"_api_select_1\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}}},{\"component\":\"Divider\",\"label\":\"2. 部署与构建环境\",\"icon\":\"radix-icons:divider-horizontal\",\"field\":\"_divider_2\",\"colProps\":{\"span\":24},\"componentProps\":{\"orientation\":\"center\",\"dashed\":true},\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"key\":\"_divider_2\"},{\"component\":\"RadioGroup\",\"label\":\"部署类型\",\"icon\":\"carbon:radio-button-checked\",\"field\":\"deploy_type\",\"required\":true,\"colProps\":{\"span\":24},\"componentProps\":{\"defaultValue\":\"binary\",\"options\":[{\"label\":\"二进制 / 主机发布\",\"value\":\"binary\"},{\"label\":\"Docker 容器部署\",\"value\":\"docker\"},{\"label\":\"K8S 容器集群\",\"value\":\"k8s\"}]},\"key\":\"_radio_group_7\",\"itemProps\":{\"l