",\"colProps\":{\"span\":24},\"componentProps\":{\"options\":[{\"label\":\"node16\",\"value\":\"16\"},{\"label\":\"node18\",\"value\":\"18\"},{\"label\":\"node20\",\"value\":\"20\"},{\"label\":\"node22\",\"value\":\"22\"},{\"label\":\"node24\",\"value\":\"24\"}],\"defaultValue\":\"16\"},\"key\":\"_select_8\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{},\"help\":\"不选默认node16\"},\"vShow\":\"values.project_type === \'frontend\'\"},{\"component\":\"InputTextArea\",\"label\":\"构建命令\",\"icon\":\"ant-design:file-text-filled\",\"field\":\"frontend_build_command\",\"colProps\":{\"span\":24},\"componentProps\":{\"rows\":3,\"defaultValue\":\"npm install --prefer-offline --registry=https://registry.npmmirror.com/ --loglevel=error && npm run build:stage -- --silent\"},\"key\":\"_input_text_area_16\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"vShow\":\"values.project_type === \'frontend\'\"},{\"component\":\"InputTextArea\",\"label\":\"构建命令\",\"icon\":\"ant-design:file-text-filled\",\"field\":\"backend_build_command\",\"colProps\":{\"span\":24},\"componentProps\":{\"rows\":3,\"defaultValue\":\"mvn clean package -Dmaven.test.skip=true -T 1C -q\"},\"key\":\"_input_text_area_17\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"vShow\":\"values.project_type === \'backend\'\"},{\"component\":\"Input\",\"label\":\"产出目录\",\"icon\":\"bi:input-cursor-text\",\"field\":\"frontend_output_dir\",\"colProps\":{\"span\":24},\"componentProps\":{\"defaultValue\":\"dist\",\"placeholder\":\"例如 dist 或 build\"},\"key\":\"_input_frontend_dir\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{},\"help\":\"前端编译产物目录，不填默认 dist\"},\"vShow\":\"values.project_type === \'frontend\'\"},{\"field\":\"_grid_23\",\"component\":\"Grid\",\"label\":\"后端参数配置分组\",\"icon\":\"icon-grid\",\"componentProps\":{},\"columns\":[{\"span\":8,\"children\":[{\"component\":\"Input\",\"label\":\"模块路径\",\"icon\":\"bi:input-cursor-text\",\"field\":\"module_path\",\"colProps\":{\"span\":24,\"offset\":0,\"order\":0,\"pull\":0,\"push\":0},\"componentProps\":{\"defaultValue\":\".\"},\"key\":\"_input_20\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"vShow\":\"values.project_type === \'backend\'\"}]},{\"span\":8,\"children\":[{\"component\":\"Select\",\"label\":\"配置文件\",\"icon\":\"gg:select\",\"field\":\"use_config\",\"colProps\":{\"span\":24},\"componentProps\":{\"defaultValue\":\"dev\",\"options\":[{\"label\":\"dev\",\"value\":\"dev\"},{\"label\":\"test\",\"value\":\"test\"},{\"label\":\"stage\",\"value\":\"stage\"},{\"label\":\"pre\",\"value\":\"pre\"},{\"label\":\"prod\",\"value\":\"prod\"}]},\"key\":\"_select_22\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"vShow\":\"values.project_type === \'backend\'\"}]},{\"span\":8,\"children\":[{\"component\":\"Input\",\"label\":\"监听端口\",\"icon\":\"bi:input-cursor-text\",\"field\":\"listen_port\",\"colProps\":{\"span\":24,\"offset\":0},\"componentProps\":{\"defaultValue\":\"8080\"},\"key\":\"_input_18\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"vShow\":\"values.project_type === \'backend\'\"}]}],\"colProps\":{\"span\":24},\"options\":{\"gutter\":0},\"key\":\"_grid_23\",\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"vShow\":\"values.project_type === \'backend\'\"}],\"layout\":\"horizontal\",\"labelLayout\":\"flex\",\"labelWidth\":100,\"labelCol\":{\"span\":4},\"wrapperCol\":{\"span\":20},\"currentItem\":{\"component\":\"Divider\",\"label\":\"2. 部署与构建环境\",\"icon\":\"radix-icons:divider-horizontal\",\"field\":\"_divider_2\",\"colProps\":{\"span\":24},\"componentProps\":{\"orientation\":\"center\",\"dashed\":true},\"itemProps\":{\"labelCol\":{},\"wrapperCol\":{}},\"key\":\"_divider_2\"},\"activeKey\":4}'),
